exec(open('tools/common.py').read())
# Intermediate unit 68 – Power and authority. Bám sách: trang 140–141 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# do away with (u1), back sb up = ủng hộ (u38), carry out = thực hiện (u45) đã có thẻ cùng nghĩa → chỉ nhắc.
# Nghĩa mới: stand for (ứng cử; u19 = viết tắt), bring in (ban hành luật), enter into (ký kết thỏa thuận; u21 = tham gia tranh luận) → thẻ có sense.
theory = (
 H("A", "The start of a political career", "Khởi đầu sự nghiệp chính trị")
 + P("Asked why she decided to <b>stand for</b> Parliament (try to get elected), a politician says years of social work showed her how divided the country was. She wanted to help <b>bring in</b> laws (introduce them) to narrow the gap, <b>do away with</b> taxes for the poorest (abolish them – card in Unit 1), <b>clamp down</b> on rich tax dodgers (act to stop them; noun <b>clampdown</b>) and <b>stand up for</b> her principles (defend them).",
     "Được hỏi vì sao quyết định <b>stand for</b> Nghị viện (ra ứng cử), một chính trị gia kể nhiều năm làm công tác xã hội cho bà thấy đất nước chia rẽ ra sao. Bà muốn góp phần <b>bring in</b> luật (ban hành) để thu hẹp khoảng cách, <b>do away with</b> thuế cho người nghèo nhất (bãi bỏ – đã có thẻ ở bài 1), <b>clamp down</b> người giàu trốn thuế (siết chặt; danh từ <b>clampdown</b>) và <b>stand up for</b> các nguyên tắc của mình (bảo vệ).")
 + H("B", "Life in Parliament", "Đời sống nghị trường")
 + P("Once elected, how did she <b>go ahead</b> with her plans (start doing them; noun <b>go-ahead</b> = permission)? Some MPs <b>backed</b> her <b>up</b> (supported her – card in Unit 38), but powerful ones warned her that the party had <b>entered into</b> an agreement with business leaders (officially agreed to it) not to raise taxes on the rich. She <b>stood up to</b> them (refused to do what they wanted): she was not there to <b>carry out</b> big business’s wishes (do what she was told – card in Unit 45).",
     "Đắc cử rồi, bà <b>go ahead</b> với kế hoạch thế nào (bắt tay thực hiện; danh từ <b>go-ahead</b> = sự cho phép)? Vài nghị sĩ <b>backed</b> bà <b>up</b> (ủng hộ – đã có thẻ ở bài 38), nhưng những người có thế lực cảnh báo đảng đã <b>entered into</b> thỏa thuận với giới doanh nhân (chính thức cam kết) không tăng thuế người giàu. Bà <b>stood up to</b> họ (cứng rắn không chịu theo): bà không vào nghị viện để <b>carry out</b> ý muốn của giới tài phiệt (làm theo lệnh – đã có thẻ ở bài 45).")
 + H("C", "Forming a new party", "Lập đảng mới")
 + P("Not every MP would <b>stand by</b> her (keep supporting her), but a few loyal ones <b>stuck by</b> her (stayed loyal), and together they <b>broke away</b> (left the group) to start a new party. None was re-elected, but they still hope one day to <b>carry out</b> their plans for a fairer society (do what they promised).",
     "Không phải nghị sĩ nào cũng <b>stand by</b> bà (tiếp tục ủng hộ), nhưng vài người trung thành vẫn <b>stuck by</b> bà (sát cánh), và họ cùng <b>broke away</b> (tách ra) lập đảng mới. Không ai tái đắc cử, nhưng họ vẫn mong một ngày <b>carry out</b> kế hoạch vì một xã hội công bằng hơn (thực hiện điều đã hứa).")
)
